using Hospital.Web.Models; using Microsoft.AspNetCore.Identity.EntityFrameworkCore; using Microsoft.EntityFrameworkCore;
namespace Hospital.Web.Data; public class AppDbContext(DbContextOptions<AppDbContext> options):IdentityDbContext(options){public DbSet<Branch> Branches=>Set<Branch>(); public DbSet<Specialty> Specialties=>Set<Specialty>(); public DbSet<Clinic> Clinics=>Set<Clinic>(); public DbSet<Doctor> Doctors=>Set<Doctor>(); public DbSet<MedicalService> MedicalServices=>Set<MedicalService>(); public DbSet<Patient> Patients=>Set<Patient>(); protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b); b.Entity<Patient>().HasIndex(x=>x.FileNumber).IsUnique(); b.Entity<MedicalService>().Property(x=>x.Price).HasPrecision(18,2);}}
